Lemma to_outcomes_star_only : forall ms model U,
  to_outcomes ms model U ->
  m_halted model = None ->
  m_vm_lazy model = [] ->
  forall tr c, star segs (mkCfg ms model) tr c ->
    exists o, U o /\ is_prefix tr (outcome_trace (m_fs model) o).
Proof.
