Lemma tmw_star_admits_succ : forall ms model bf cf bs cs,
  tmw ms model bf cf bs cs ->
  bufs_modeled bs ->
  m_halted model = None -> m_vm_lazy model = [] -> fd1chan model ->
  exists c, star segs (mkCfg ms model) (wevents bs ++ [ExitEv cs (m_fs model)]) c.
Proof.
