Lemma drain_obs_iff : forall pc ph sp brk0 mb rnd lim inp a0,
  to_rd a0 (init_machine_state segs pc ph sp rnd (in_argv inp) (in_envp inp) (in_uid inp) (in_hwcap inp)) ->
