Fixpoint outside (a : word) (rs : list (word * Z)) : Prop :=
  match rs with
  | [] => True
  | (b, n) :: rs' => ~ in_rng a b n /\ outside a rs'
  end.

Lemma outside_app : forall a rs1 rs2, outside a (rs1 ++ rs2) <-> outside a rs1 /\ outside a rs2.
Proof.
